-- PT105-S4-Q1. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT105-S4-Q1$batch07$ AND q.stimulus=$batch07$Shortly after Isaac Newton circulated some of his theories of light in 1672, his colleague Robert Hooke claimed that most of those theories were based on Hooke's own work. A modern reader might interpret Newton's famous comment, "if I have seen further it is by standing on the shoulders of giants, "as a conciliatory gesture acknowledging indebtedness to Hooke and other contemporary scientists for some of his theories. Conciliatory gestures acknowledging indebtedness were uncharacteristic of Newton, however, and in his day such allusions to "giants" typically referred to the ancient Greeks, not to contemporary scientists.$batch07$ AND q.prompt=$batch07$The statements in the passage, if true, most strongly support which one of the following?$batch07$ AND q.correct_choice=$batch07$A$batch07$) THEN RAISE EXCEPTION 'Question changed: PT105-S4-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT105-S4-Q1$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S4-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT105-S4-Q1$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Hooke claimed most of Newton's light theories came from Hooke's work. A modern reader might read Newton's "shoulders of giants" line as a polite nod to Hooke and other contemporaries. However, Newton didn't make conciliatory gestures like that, and in his day "giants" usually meant the ancient Greeks.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$The "however" is the author rebutting the modern reading. Both facts after it point the same way: the line probably wasn't a nod to Hooke. It wasn't Newton's style, and "giants" pointed to the Greeks, not to contemporaries.$batch07$), (2, $batch07$Goal$batch07$, $batch07$Newton probably didn't mean the comment as credit to Hooke.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT105-S4-Q1$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$This is the modern reading, denied. The author gives two reasons to doubt that Newton meant the line as an acknowledgment of Hooke.$batch07$), ($batch07$B$batch07$, $batch07$The passage is about what Newton's comment meant, not about whether Newton took credit for Hooke's work.$batch07$), ($batch07$C$batch07$, $batch07$Nothing says what Newton thought about where Hooke's ideas came from.$batch07$), ($batch07$D$batch07$, $batch07$This is the most popular wrong answer. The passage points away from contemporaries altogether: "giants" usually meant the ancient Greeks, "not ... contemporary scientists". So if anything, Newton was not crediting other contemporaries either.$batch07$), ($batch07$E$batch07$, $batch07$Whether Newton knew Hooke's work is never discussed.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT105-S4-Q1$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
